package za.co.lepetse.admin;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.mock.web.MockMultipartFile;
import com.fasterxml.jackson.databind.*;
import java.util.*;import java.io.*;import java.util.zip.*;
import org.apache.pdfbox.pdmodel.*;import org.apache.pdfbox.pdmodel.font.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc @Transactional
@EnabledIfEnvironmentVariable(named="LEPETSE_DB_TEST",matches="true")
class AdminTenderApplicationsTest {
 @Autowired MockMvc http;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;
 byte[] pdf(String text)throws Exception{try(var d=new PDDocument()){var p=new PDPage();d.addPage(p);if(!text.isBlank())try(var stream=new PDPageContentStream(d,p)){stream.beginText();stream.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),12);stream.newLineAtOffset(40,700);stream.showText(text);stream.endText();}var out=new ByteArrayOutputStream();d.save(out);return out.toByteArray();}}
 long opportunity()throws Exception{var d=new HashMap<String,Object>();for(String k:List.of("scope","rationale","requirements","briefing","submission","documents","source","instructions","phone"))d.put(k,"");d.putAll(Map.of("title","TEST tender application","buyer","Test office "+UUID.randomUUID(),"reference","TEST-APP","closing","2099-12-01T09:00:00Z","recommendation","possible","contact","Test Buyer","email","buyer@example.invalid","buyerType","government"));var res=http.perform(post("/api/admin/opportunities").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsString(Map.of("details",d)))).andExpect(status().isOk()).andReturn();return json.readTree(res.getResponse().getContentAsString()).get("id").asLong();}
 long upload(Long opp,String kind,String label,String expiry)throws Exception{var req=multipart(opp==null?"/api/admin/company-documents":"/api/admin/opportunities/"+opp+"/application/files").file(new MockMultipartFile("file","test.pdf","application/pdf",pdf("All bidders must submit a signed SBD 4 declaration."))).param("label",label).param("kind",kind).param("documentType","csd");if(expiry!=null)req.param("expiresOn",expiry);var res=http.perform(req.with(user("owner").roles("ADMIN")).with(csrf())).andExpect(status().isOk()).andReturn();return json.readTree(res.getResponse().getContentAsString()).get("id").asLong();}
 Map<String,Object> requirement(){var r=new HashMap<String,Object>();r.putAll(Map.of("title","Signed SBD 4","category","document","mandatory",true,"status","todo","notes","","signatureRequired",true,"signatureConfirmed",false,"sourceExcerpt",""));return r;}
 void add(long id,Map<String,Object> r,int status)throws Exception{http.perform(post("/api/admin/opportunities/"+id+"/application/requirements").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsString(Map.of("reviewed",true,"requirements",List.of(r))))).andExpect(status().is(status));}
 @Test void extractedSuggestionsNeedReviewAndPreservePageEvidenceWithoutDuplicates()throws Exception{long id=opportunity(),file=upload(id,"tender","Original tender",null);http.perform(post("/api/admin/opportunities/"+id+"/application/files/"+file+"/extract").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content("{}")).andExpect(status().isOk()).andExpect(jsonPath("$.extraction.suggestions[0].page").value(1)).andExpect(jsonPath("$.extraction.suggestions[0].mandatory").value(true)).andExpect(jsonPath("$.extraction.suggestions[0].category").value("document"));var r=requirement();r.put("sourceFileId",file);r.put("sourcePage",1);r.put("sourceExcerpt","All bidders must submit a signed SBD 4 declaration.");http.perform(post("/api/admin/opportunities/"+id+"/application/requirements").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsString(Map.of("reviewed",false,"requirements",List.of(r))))).andExpect(status().isBadRequest());add(id,r,200);add(id,r,200);assertThat(db.queryForObject("select count(*) from tender_requirement where opportunity_id=?",Integer.class,id)).isEqualTo(1);http.perform(get("/api/admin/opportunities/"+id+"/application").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.requirements[0].source_page").value(1)).andExpect(jsonPath("$.requirements[0].status").value("todo")).andExpect(jsonPath("$.ready").value(false)).andExpect(jsonPath("$.checks.length()").value(3)).andExpect(jsonPath("$.checks[0].complete").value(true));}
 @Test void expiredEvidenceAndMissingSignaturesRemainOutstanding()throws Exception{long id=opportunity(),file=upload(null,"company","Expired CSD report","2000-01-01");var r=requirement();r.put("status","done");add(id,r,400);r.put("documentId",file);add(id,r,400);r.put("signatureConfirmed",true);add(id,r,200);var res=http.perform(get("/api/admin/opportunities/"+id+"/application").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertThat(res).contains("Expired document: Expired CSD report");r.put("status","not_applicable");add(id,r,400);}
 @Test void foreignOpportunityEvidenceCannotBeLinked()throws Exception{long first=opportunity(),second=opportunity(),file=upload(second,"returnable","Signed form",null);var r=requirement();r.put("documentId",file);add(first,r,400);}
 @Test void downloadPackIncludesOnlySelectedEvidenceAndShowsDraftStatus()throws Exception{long id=opportunity(),selected=upload(null,"company","Selected company document",null);long unselected=upload(null,"company","Private unrelated company document",null);long original=upload(id,"tender","Original tender",null),proof=upload(id,"proof","Proof",null);var r=requirement();r.put("documentId",selected);add(id,r,200);byte[] pack=http.perform(get("/api/admin/opportunities/"+id+"/application/pack").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(content().contentType("application/zip")).andReturn().getResponse().getContentAsByteArray();var names=new ArrayList<String>();String summary="";try(var zip=new ZipInputStream(new ByteArrayInputStream(pack))){for(var e=zip.getNextEntry();e!=null;e=zip.getNextEntry()){names.add(e.getName());var bytes=zip.readAllBytes();if(e.getName().equals("Application-checklist.txt"))summary=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);}}assertThat(summary).contains("DRAFT PACK");assertThat(names).contains("documents/"+selected+"-test.pdf").doesNotContain("documents/"+unselected+"-test.pdf","documents/"+original+"-test.pdf","documents/"+proof+"-test.pdf");}
 @Test void submissionIsExplicitAndIdempotentAndKeepsProof()throws Exception{long id=opportunity(),proof=upload(id,"proof","Portal receipt",null);var r=new HashMap<String,Object>(Map.of("submissionKey",UUID.randomUUID(),"submittedAt","2026-01-01T08:00:00Z","channel","Portal","recipient","Official procurement portal","confirmation","TEST-RECEIPT","proofFileId",proof,"confirmed",true));for(int i=0;i<2;i++)http.perform(post("/api/admin/opportunities/"+id+"/application/submissions").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsString(r))).andExpect(status().isOk());assertThat(db.queryForObject("select count(*) from tender_submission where opportunity_id=?",Integer.class,id)).isEqualTo(1);assertThat(db.queryForObject("select progress from work_opportunity where id=?",String.class,id)).isEqualTo("submitted");r.put("recipient","Changed recipient");http.perform(post("/api/admin/opportunities/"+id+"/application/submissions").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsString(r))).andExpect(status().isConflict());}
 @Test void privateFilesRequireAdminAndUploadsNeedCsrf()throws Exception{long file=upload(null,"company","Company registration",null);http.perform(get("/api/admin/tender-files/"+file+"/download")).andExpect(status().isUnauthorized());http.perform(get("/api/admin/tender-files/"+file+"/download").with(user("viewer").roles("USER"))).andExpect(status().isForbidden());http.perform(get("/api/admin/tender-files/"+file+"/download").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(content().contentType("application/octet-stream"));http.perform(multipart("/api/admin/company-documents").file(new MockMultipartFile("file","fake.pdf","application/pdf","not a PDF".getBytes())).param("label","Fake").with(user("owner").roles("ADMIN"))).andExpect(status().isForbidden());http.perform(multipart("/api/admin/company-documents").file(new MockMultipartFile("file","fake.pdf","application/pdf","not a PDF".getBytes())).param("label","Fake").with(user("owner").roles("ADMIN")).with(csrf())).andExpect(status().isBadRequest());}
 @Test void staleChecklistEditsConflictAndBlankPdfsDoNotInventRequirements()throws Exception{long id=opportunity();var r=requirement();add(id,r,200);long item=db.queryForObject("select id from tender_requirement where opportunity_id=?",Long.class,id);r.put("version",1);String body=json.writeValueAsString(r);for(int expected:List.of(200,409))http.perform(post("/api/admin/opportunities/"+id+"/application/requirements/"+item).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(body)).andExpect(status().is(expected));var extract=new TenderRequirementExtractor().extract(pdf(""));assertThat(extract.suggestions()).isEmpty();assertThat(extract.warning()).contains("OCR");}
 @Test void packUsesTheExistingFinalisedQuotationAndRechecksExpiry()throws Exception{var flow=new AdminPricingWorkflowTest();flow.http=http;flow.db=db;flow.json=json;long request=flow.request("business");flow.approve(request);long quotation=flow.finalise(request);long id=opportunity();db.update("update work_opportunity set rfq_id=? where id=?",request,id);var r=requirement();r.put("category","eligibility");r.put("status","done");r.put("signatureRequired",false);add(id,r,200);http.perform(get("/api/admin/opportunities/"+id+"/application").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.ready").value(true));byte[] pack=http.perform(get("/api/admin/opportunities/"+id+"/application/pack").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();boolean found=false;try(var zip=new ZipInputStream(new ByteArrayInputStream(pack))){for(var e=zip.getNextEntry();e!=null;e=zip.getNextEntry()){byte[] bytes=zip.readAllBytes();if(e.getName().startsWith("Quotation-")){found=true;try(var pdf=org.apache.pdfbox.Loader.loadPDF(bytes)){assertThat(new org.apache.pdfbox.text.PDFTextStripper().getText(pdf)).contains("Customer blue pens").doesNotContain("SECRET-SKU","PRIVATE SUPPLIER");}}}}assertThat(found).isTrue();db.update("update quotation set valid_until='2000-01-01' where id=?",quotation);http.perform(get("/api/admin/opportunities/"+id+"/application").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.ready").value(false));}
 @Test void extraPackDocumentsCanBeExcludedWithoutDeletingHistory()throws Exception{long id=opportunity(),file=upload(id,"returnable","Old signed form",null);http.perform(post("/api/admin/opportunities/"+id+"/application/files/"+file+"/pack").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content("{\"included\":false}")).andExpect(status().isOk());assertThat(db.queryForObject("select pack_included from tender_file where id=?",Boolean.class,file)).isFalse();http.perform(get("/api/admin/tender-files/"+file+"/download").with(user("owner").roles("ADMIN"))).andExpect(status().isOk());byte[] bytes=http.perform(get("/api/admin/opportunities/"+id+"/application/pack").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();try(var zip=new ZipInputStream(new ByteArrayInputStream(bytes))){for(var entry=zip.getNextEntry();entry!=null;entry=zip.getNextEntry())assertThat(entry.getName()).doesNotContain("documents/"+file+"-");}}
}
